// Parse incoming MCP request and route to handler
const input = $input.first().json;
const body = input.body || input;
const action = body.action || 'help';
const params = body.params || {};
const request_id = body.request_id || 'ag-' + Date.now();

// Define all available workflows (from n8n Cloud)
const workflows = [
  { id: '4Qn2t3z6HgJwEBEH', name: 'Doc Chain - Release', active: true },
  { id: '85OVKyBKrzQFA1kg', name: 'Doc Chain - Trigger', active: true },
  { id: '9kOmwTpPU5SAPvxE', name: 'Doc Chain - Distributor', active: true },
  { id: 'CHI7LYvp70EPOmUi', name: 'Doc Chain - PR Review', active: true },
  { id: 'LpZ7jA5sxXy4QieO', name: 'Doc Chain - Agent', active: true },
  { id: 'NF3XjMIBrimCTYja', name: 'Doc Chain - State Reconciliation', active: true },
  { id: 'PARiTxsX57k0ny6P', name: 'Doc Chain - Claude Bridge', active: true },
  { id: 'b2hw3xA7DvFn7XCV', name: 'Doc Chain - Claude Antigravity Bridge', active: true },
  { id: 'btKQeVWvPRe6eqPP', name: 'Doc Chain - Errors', active: true },
  { id: 'r6GoavRSv9pjatqE', name: 'Doc Chain - Claude Bridge v2', active: true },
  { id: 'tSWCWLMGOBR1uw87', name: 'Doc Chain - Staleness', active: true }
];

// Define available tools
const tools = [
  { name: 'list_workflows', description: 'List all n8n workflows', parameters: {} },
  { name: 'get_workflow', description: 'Get workflow info by ID', parameters: { workflow_id: 'string' } },
  { name: 'get_executions', description: 'View recent executions', parameters: { limit: 'number' } },
  { name: 'trigger_workflow', description: 'Trigger github-doc-trigger', parameters: { modified_files: 'array' } },
  { name: 'health', description: 'Check MCP Bridge health', parameters: {} }
];

// Handle each action
let response = {};

switch (action) {
  case 'health':
    response = {
      success: true,
      action: 'health',
      status: 'healthy',
      server: 'antigravity-mcp-bridge',
      n8n_cloud: 'gitlitreview.app.n8n.cloud',
      timestamp: new Date().toISOString(),
      message: 'n8n MCP Bridge is operational'
    };
    break;

  case 'list_workflows':
    response = {
      success: true,
      action: 'list_workflows',
      count: workflows.length,
      workflows: workflows
    };
    break;

  case 'get_workflow':
    const wfId = params.workflow_id;
    if (!wfId) {
      response = { success: false, error: 'workflow_id required' };
    } else {
      const wf = workflows.find(w => w.id === wfId);
      response = {
        success: true,
        action: 'get_workflow',
        workflow: wf || { id: wfId, message: 'Not in cached list' },
        ui_url: `https://gitlitreview.app.n8n.cloud/workflow/${wfId}`
      };
    }
    break;

  case 'get_executions':
    response = {
      success: true,
      action: 'get_executions',
      message: 'View executions in n8n UI',
      ui_url: 'https://gitlitreview.app.n8n.cloud/executions',
      limit: params.limit || 10
    };
    break;

  case 'trigger_workflow':
    const files = params.modified_files;
    if (!files || !Array.isArray(files) || files.length === 0) {
      response = { success: false, error: 'modified_files array required' };
    } else {
      response = {
        success: true,
        action: 'trigger_workflow',
        message: 'Use POST to /webhook/github-doc-trigger directly',
        target_webhook: 'https://gitlitreview.app.n8n.cloud/webhook/github-doc-trigger',
        modified_files: files
      };
    }
    break;

  case 'help':
  default:
    response = {
      success: true,
      action: 'help',
      mcp_version: '1.0.0',
      server: 'antigravity-mcp-bridge',
      tools: tools
    };
    break;
}

response.request_id = request_id;
return response;
